Lemma cost_split cr :
  PMSP.credit_le (PMSPA.scA L (PQRHA.rdr_cost (PMSPA.HV L ar))) cr ->
  PMSP.credit_le (PMSPA.scA L (PM.credit_add (PM.cost1 (PMSPA.HV L ar) PM.CHUNK) (PM.cost1 (PMSPA.HV L ar) PQMA.PSZ))) cr
  /\ forall cr1, PMSP.credit_keep cr cr1 (PMSPA.scA L (PM.credit_add (PM.cost1 (PMSPA.HV L ar) PM.CHUNK) (PM.cost1 (PMSPA.HV L ar) PQMA.PSZ))) (PMSPA.scA L PMSP.cr0) ->
     PMSP.credit_le (PMSPA.scA L (PM.cost1 (PMSPA.HV L ar) PQMA.LSZ)) cr1
     /\ forall cr2, PMSP.credit_keep cr1 cr2 (PMSPA.scA L (PM.cost1 (PMSPA.HV L ar) PQMA.LSZ)) (PMSPA.scA L PMSP.cr0) ->
        PMSP.credit_keep cr cr2 (PMSPA.scA L (PQRHA.rdr_cost (PMSPA.HV L ar))) (PMSPA.scA L PMSP.cr0).
